changes.evals/skills/commit-message-writer/cases:
{
  "kind": "task",
  "prompt": "I fixed the retry loop in client.go: it now gives up after five attempts instead of retrying forever when the gateway is down. The change is staged. Write the commit message.",
  "expectations": [
    {
      "text": "The subject is imperative and at most 72 characters",
      "source": "format",
      "judged": {
        "question": "Is the first line of the message an imperative subject of 72 characters or fewer?",
        "pass": "Yes when the subject is a command, such as 'Stop retrying after five attempts', and fits in 72.",
        "fail": "No when it is past tense, a description, or longer than 72 characters.",
        "examples": {
          "pass": [
            "Stop retrying a failed charge after five attempts"
          ],
          "fail": [
            "Fixed the retry loop so that it no longer keeps going forever when the gateway is down"
          ]
        }
      }
    },
    {
      "text": "A blank line separates the subject from the body",
      "source": "format",
      "judged": {
        "question": "Is the second line of the message blank, with the body after it?",
        "pass": "Yes when line 2 is empty and the body starts on line 3.",
        "fail": "No when the body starts on line 2, or there is no body.",
        "examples": {
          "pass": [
            "Subject, an empty line, then two lines of body."
          ],
          "fail": [
            "Subject and body on consecutive lines."
          ]
        }
      }
    },
    {
      "text": "The body says what changed and why",
      "source": "format",
      "judged": {
        "question": "Does the body say that retries now stop after five attempts, and why?",
        "pass": "Yes when it names the change and its reason: a down gateway made the loop run forever.",
        "fail": "No when it says only what changed, or repeats the subject.",
        "examples": {
          "pass": [
            "Retries stop after five attempts, because a down gateway kept the loop running forever."
          ],
          "fail": [
            "Update client.go."
          ]
        }
      }
    }
  ]
}

